/*  Esta funcion realiza el calcula del IVA
    multiplicando el subtotal por el porsentaje del IVA
    que en el estandar de Guatemala es del 12% (0.12)
    asi regresando el valor del IVA de la compra
*/
export function calcularIVA(subtotal) {
    return subtotal * 0.12;
}
